# owner: platform
"""Snap span edges to a payroll step, then label them."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour: {step}"
        )


def _snap(minute: int, step: int) -> int:
    return (minute + step // 2) // step * step


def _duration(span: Span) -> str:
    hours, rest = divmod(span.minutes, 60)
    return f"{hours}h {rest}m"


def _label_for(span: Span, step: int) -> str:
    return span_label(round_span(span, step))


# ---
def round_span(span: Span, step: int) -> Span:
    """Round both edges to the nearest step, halves up.

    Raises ValueError for a bad step, or when the span
    shrinks to nothing after rounding.
    """
    _check_step(step)
    return Span(
        _snap(span.start, step), _snap(span.end, step)
    )


# ---
def span_label(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m)."""
    return f"{format_span(span)} ({_duration(span)})"


# ---
def round_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """One label per span, after rounding to the step."""
    _check_step(step)
    return [
        _label_for(item, step) for item in spans
    ]

