# owner: platform
import unittest

from hourglass.rounding import (
    round_labels,
    round_span,
    span_label,
)
from hourglass.parsing import parse_span
from hourglass.models import Span


class RoundSpanTests(unittest.TestCase):
    def test_rounds_to_nearest(self):
        span = parse_span("08:53-17:08")
        self.assertEqual(
            round_span(span, 15), parse_span("09:00-17:15")
        )

    def test_halves_round_up(self):
        span = Span(8, 23)
        self.assertEqual(round_span(span, 15), Span(15, 30))

    def test_exact_edges_stay(self):
        span = Span(60, 120)
        self.assertEqual(round_span(span, 30), span)

    def test_end_of_day(self):
        span = Span(1400, 1440)
        result = round_span(span, 60)
        self.assertEqual(result, Span(1380, 1440))

    def test_collapsing_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(61, 64), 15)


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_span(Span(0, 60), step)

    def test_bad_step_with_no_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                round_span(Span(0, 120), step)


class LabelTests(unittest.TestCase):
    def test_label(self):
        span = parse_span("09:00-17:15")
        label = span_label(span)
        self.assertEqual(label, "09:00-17:15 (8h 15m)")

    def test_short_label(self):
        label = span_label(Span(540, 570))
        self.assertEqual(label, "09:00-09:30 (0h 30m)")

    def test_round_labels(self):
        spans = [parse_span("08:53-17:08"), Span(600, 660)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "10:00-11:00 (1h 0m)"]
        )

    def test_empty(self):
        self.assertEqual(round_labels([], 15), [])
